<?php declare(strict_types=1); ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yorum moderasyonu</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:1050px;margin:35px auto;padding:0 18px}.item{background:white;padding:18px;border-radius:12px;margin:12px 0;border:1px solid #e7ece8}.muted{color:#6d796f;font-size:13px}button{border:0;padding:9px 13px;border-radius:8px;color:white;background:#176b50;margin-right:5px}button.reject{background:#a43}
/* Consistent admin links and actions */
a{color:#176b50;text-decoration:none;transition:color .18s ease,background-color .18s ease,border-color .18s ease}a:hover{color:#104c39;text-decoration:none}td a:not([class]),.table-wrap a:not([class]){display:inline-flex;align-items:center;justify-content:center;padding:7px 11px;border:1px solid #dce9e0;border-radius:8px;background:#f5faf6;color:#176b50;font-size:12px;font-weight:750;white-space:nowrap}td a:not([class]):hover,.table-wrap a:not([class]):hover{background:#eaf4ee;border-color:#b9d8c4}button,input[type=submit]{cursor:pointer;font:inherit}button{transition:filter .18s ease,transform .18s ease}button:hover,input[type=submit]:hover{filter:brightness(.96)}
</style></head><body><main class="wrap"><h1>Misafir değerlendirmeleri</h1><p class="muted">Yalnızca tamamlanmış rezervasyonlara bağlı doğrulanmış değerlendirmeler yayınlanabilir.</p><?php foreach($reviews as $review): ?><article class="item"><strong><?= e($review['title']) ?></strong><div class="muted"><?= e($review['username']) ?> · <?= (int)$review['rating'] ?>/10 · <?= e($review['status']) ?></div><p><?= e($review['body']) ?></p><form method="post" action="/admin/reviews/status"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><button name="status" value="approved">Yayınla</button><button class="reject" name="status" value="rejected">Reddet</button></form></article><?php endforeach; ?><?php if(!$reviews): ?><p>Henüz değerlendirme bulunmuyor.</p><?php endif; ?></main></body></html>